// Pictograms for the align / distribute commands (plan 3.3).
//
// They are drawn here, as SVG primitives on the same 16 px grid the icon set
// uses (1.25 stroke, currentColor), and not added to src/brand/icons: that set
// is an accepted deliverable of its own (one file per glyph, generated by
// tools/make-icons.py) and a feature pictogram has no business changing it.
// Nothing here is fetched — the buttons work offline like the rest.

const NS = 'http://www.w3.org/2000/svg';

const box = (x, y, w, h) => `M ${x} ${y} h ${w} v ${h} h ${-w} Z`;

const PATHS = {
  // A reference edge plus two boxes pulled to it.
  'align-left': { edge: 'M 2.5 2 V 14', boxes: [box(5, 3.5, 8, 3.5), box(5, 9, 5.5, 3.5)] },
  'align-right': { edge: 'M 13.5 2 V 14', boxes: [box(3, 3.5, 8, 3.5), box(5.5, 9, 5.5, 3.5)] },
  'align-center': { edge: 'M 8 2 V 14', boxes: [box(3, 3.5, 10, 3.5), box(4.5, 9, 7, 3.5)] },
  'align-top': { edge: 'M 2 2.5 H 14', boxes: [box(3.5, 5, 3.5, 8), box(9, 5, 3.5, 5.5)] },
  'align-bottom': { edge: 'M 2 13.5 H 14', boxes: [box(3.5, 3, 3.5, 8), box(9, 5.5, 3.5, 5.5)] },
  'align-middle': { edge: 'M 2 8 H 14', boxes: [box(3.5, 3, 3.5, 10), box(9, 4.5, 3.5, 7)] },
  // Three bars with equal gaps between them.
  'distribute-h': { edge: '', boxes: [box(2, 3, 2.5, 10), box(6.75, 3, 2.5, 10), box(11.5, 3, 2.5, 10)] },
  'distribute-v': { edge: '', boxes: [box(3, 2, 10, 2.5), box(3, 6.75, 10, 2.5), box(3, 11.5, 10, 2.5)] },
};

/** An inline <svg> pictogram; unknown names give an empty svg of the right size. */
export function alignIcon(name, size = 16) {
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('width', String(size));
  svg.setAttribute('height', String(size));
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');
  svg.setAttribute('class', 'icon align-ic');
  const p = PATHS[name];
  if (!p) return svg;
  if (p.edge) {
    const edge = document.createElementNS(NS, 'path');
    edge.setAttribute('d', p.edge);
    edge.setAttribute('class', 'align-edge');
    svg.append(edge);
  }
  for (const d of p.boxes) {
    const node = document.createElementNS(NS, 'path');
    node.setAttribute('d', d);
    node.setAttribute('class', 'align-box');
    svg.append(node);
  }
  return svg;
}
